#!/usr/bin/env node
// diag-v42-replicate.mjs — word-by-word map of inputs[1], then rebuild the
// exact swap for OUR wallet (recipient/amount/minOut surgery + fresh unix ts)
// and eth_call it on drpc.
import { readFileSync } from "fs";
import { dirname, join } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
for (const line of readFileSync(join(__dirname, "..", ".env"), "utf8").split("\n")) {
  const m = line.match(/^([^#=\s][^=]*)=(.*)$/);
  if (m) process.env[m[1].trim()] = m[2].trim().replace(/^["']|["']$/g, "");
}

const RAW = "";
const UR = "0xfdf682f51fe81aa4898f0ae2163d8a55c127fbc7";
const SENDER = "217c05f5d1d1e595bbae94534540b803bfc4563b";

const { decodeFunctionData, parseAbi, toHex, encodeFunctionData } = await import("viem");
const { resolveSigner } = await import("../signer.mjs");
const signer = await resolveSigner("base");

const { args } = decodeFunctionData({ abi: parseAbi(["function execute(bytes,bytes[],uint256) payable"]), data: RAW });
const [commands, inputs] = args;
const cmdAscii = Buffer.from(toHex(commands).slice(2), "hex").toString();
const in0Ascii = Buffer.from(toHex(inputs[0]).slice(2), "hex").toString();
const in1Ascii = Buffer.from(toHex(inputs[1]).slice(2), "hex").toString();
console.log("commands ascii:", cmdAscii);
console.log("inputs[0] ascii:", in0Ascii);
console.log("inputs[1] ascii len:", in1Ascii.length, "(incl 0x)");
const body1 = in1Ascii.slice(2); // strip 0x
console.log("\ninputs[1] word map (64-hex-char words):");
for (let i = 0; i * 64 < body1.length; i++) {
  const w = body1.slice(i * 64, i * 64 + 64);
  const asInt = BigInt("0x" + w).toString();
  console.log(`  w${i}: ${w}  int=${asInt.length > 24 ? "…" : asInt} ascii=${Buffer.from(w, "hex").toString().replace(/[^\x20-\x7e]/g, ".")}`);
}
